using Mask = std::uint8_t;

inline constexpr Mask left = 1u << 0;
inline constexpr Mask right = 1u << 1;
inline constexpr Mask down = 1u << 2;
inline constexpr Mask rotate = 1u << 3;
inline constexpr Mask drop = 1u << 4;

inline constexpr Mask known = left | right | down | rotate | drop;

inline constexpr bool has_any(Mask value, Mask bits) noexcept {
    return (value & bits) != 0;
}

inline constexpr bool has_all(Mask value, Mask bits) noexcept {
    return (value & bits) == bits;
}

const unsigned directions = static_cast<unsigned>(left | right);
const Mask keep = static_cast<Mask>(~directions);
Mask mask = static_cast<Mask>(left | right | rotate); // 11
mask = static_cast<Mask>(mask & keep);              // 8

#pragma once

namespace study_input {

// One simulation tick's semantic input.
// horizontal: -1 = left, 0 = neutral, +1 = right.
struct Intent {
    int horizontal;
    bool clockwise;
    bool soft_drop = false;
    bool hard_drop = false;
};

} // namespace study_input

inline std::optional<Mask> encode(const Intent& intent) noexcept {
    if (intent.horizontal < -1 || intent.horizontal > 1) {
        return std::nullopt;
    }
    Mask mask = 0;
    if (intent.horizontal < 0) {
        mask |= left;
    }
    if (intent.horizontal > 0) {
        mask |= right;
    }
    if (intent.clockwise) {
        mask |= rotate;
    }
    if (intent.soft_drop) {
        mask |= down;
    }
    if (intent.hard_drop) {
        mask |= drop;
    }
    return mask;
}

inline constexpr bool valid(unsigned value) noexcept {
    return (value & ~static_cast<unsigned>(known)) == 0u;
}

inline std::optional<Intent> decode(unsigned value) noexcept {
    if (!valid(value)) {
        return std::nullopt;
    }
    const Mask mask = static_cast<Mask>(value);
    int horizontal = 0;
    if (has_any(mask, left) && !has_any(mask, right)) {
        horizontal = -1;
    } else if (has_any(mask, right) && !has_any(mask, left)) {
        horizontal = +1;
    }
    Intent intent{horizontal, has_any(mask, rotate)};
    intent.soft_drop = has_any(mask, down);
    intent.hard_drop = has_any(mask, drop);
    return intent;
}

void capture(bool left_pressed, bool right_pressed, bool up,
             bool downHeld = false, bool spacePressed = false) noexcept {
    Mask edges = 0;
    if (left_pressed) {
        edges |= left;
    }
    if (right_pressed) {
        edges |= right;
    }
    if (up) {
        edges |= rotate;
    }
    if (spacePressed) {
        edges |= drop;
    }
    pending_ |= edges;
    // Held-state sample: replace, do not latch.
    soft_drop_ = downHeld;
}

Intent consume() noexcept {
    // Only allowed bits are ever stored, so decode() cannot fail here.
    return *decode(consume_mask());
}

// Drain the pending mask and fold in the current held-state sample.
//
// Edges are consumed once (cleared here). soft_drop_ is a level and is
// re-reported on EVERY call until a later capture replaces it. A raw
// left+right pair is preserved in the raw mask; decode() normalizes it to
// a neutral horizontal.
Mask consume_mask() noexcept {
    Mask mask = pending_;
    pending_ = 0;
    if (soft_drop_) {
        mask |= down;
    }
    return mask;
}
